const items = $input.all();
if (items.length !== 1) throw new Error('SAFE PDF Input requiere exactamente 1 item por invocación');
const item = items[0];
const j = item.json ?? {};
if (j.dry_run !== true || j.write_enabled !== false || j.auth_used !== false) throw new Error('Input no es SAFE/DRY RUN');
if (!/^[0-9a-f]{64}$/.test(String(j.correlation_id ?? '').toLowerCase())) throw new Error('correlation_id SHA-256 inválido');
return [{ json: { safe_envelope: j, correlation_id: String(j.correlation_id).toLowerCase() } }];

const items = $input.all();
if (items.length !== 1) throw new Error('Rejoin SAFE requiere exactamente 1 item por invocación');
const j = items[0].json ?? {};
const e = j.safe_envelope;
if (!e || e.dry_run !== true || e.write_enabled !== false || e.auth_used !== false) throw new Error('Envelope SAFE perdido tras extracción');
const cid = String(j.correlation_id ?? '').toLowerCase();
if (!/^[0-9a-f]{64}$/.test(cid) || String(e.correlation_id ?? '').toLowerCase() !== cid) throw new Error('Correlación SHA-256 perdida');
const extractedText = typeof j.text === 'string' ? j.text : (typeof j.data === 'string' ? j.data : '');
if (!extractedText.trim()) throw new Error('Extract From File no produjo texto');
return [{ json: { correlation_id: cid, dry_run: true, write_enabled: false, auth_used: false, extraction: { text: extractedText }, provenance: e.provenance, work_item: e.work_item } }];
